class StrictlyAfterAndTruncation(unittest.TestCase):
    def test_strictly_after_exact_minute(self):
        self.assertEqual(next_run("* * * * *", D(2026, 10, 11, 12, 0)), D(2026, 10, 11, 12, 1))

    def test_seconds_dropped(self):
        self.assertEqual(next_run("* * * * *", D(2026, 10, 11, 12, 0, 30)), D(2026, 10, 11, 12, 1))

    def test_last_second_of_minute(self):
        self.assertEqual(next_run("* * * * *", D(2026, 10, 11, 12, 0, 59)), D(2026, 10, 11, 12, 1))

    def test_microseconds_dropped(self):
        self.assertEqual(next_run("* * * * *", D(2026, 10, 11, 12, 0, 59, 999999)), D(2026, 10, 11, 12, 1))

    def test_seconds_do_not_skip_a_matching_minute(self):
        # 12:00:30 truncates to 12:00, so 12:01 is the first strictly-later minute
        self.assertEqual(next_run("1 12 * * *", D(2026, 10, 11, 12, 0, 30)), D(2026, 10, 11, 12, 1))

    def test_result_is_naive_and_seconds_zero(self):
        r = next_run("5 * * * *", D(2026, 10, 11, 12, 0, 7, 3))
        self.assertIsNone(r.tzinfo)
        self.assertEqual((r.second, r.microsecond), (0, 0))

    def test_year_rollover(self):
        self.assertEqual(next_run("0 0 * * *", D(2026, 12, 31, 23, 59)), D(2027, 1, 1, 0, 0))


