class DomDowRules(unittest.TestCase):
    def test_both_restricted_is_or(self):
        # every 13th OR every Friday; from 2026-10-11, Friday 10-16 comes before 13th of Nov
        self.assertEqual(next_run("0 0 13 * FRI", D(2026, 10, 11)), D(2026, 10, 13))
        self.assertEqual(next_run("0 0 13 * FRI", D(2026, 10, 13)), D(2026, 10, 16))

    def test_both_restricted_or_friday_first(self):
        self.assertEqual(next_run("0 0 20 * FRI", D(2026, 10, 14)), D(2026, 10, 16))

    def test_dom_only_when_dow_star(self):
        self.assertEqual(next_run("0 0 13 * *", D(2026, 10, 11)), D(2026, 11, 13))

    def test_dow_only_when_dom_star(self):
        self.assertEqual(next_run("0 0 * * FRI", D(2026, 10, 17)), D(2026, 10, 23))

    def test_both_star_every_day(self):
        self.assertEqual(next_run("0 0 * * *", D(2026, 10, 11)), D(2026, 10, 12))

    def test_or_rule_with_leap_feb_and_monday(self):
        # 0 0 29 2 MON: Feb 29 OR any Monday in Feb -> first Monday of Feb 2027 is Feb 1
        self.assertEqual(next_run("0 0 29 2 MON", D(2026, 10, 11)), D(2027, 2, 1))


class Malformed(unittest.TestCase):
    bad = [
        "",
        "* * * *",            # 4 fields
        "* * * * * *",        # 6 fields
        "*  * * * *",         # double space
        " * * * * *",         # leading space
        "* * * * * ",         # trailing space
        "60 * * * *",
        "* 24 * * *",
        "* * 0 * *",
        "* * 32 * *",
        "* * * 0 *",
        "* * * 13 *",
        "* * * * 8",
        "* * * * 9-10",
        "5-3 * * * *",        # backwards range
        "*/0 * * * *",        # zero step
        "*/-1 * * * *",
        "5/10 * * * *",       # step on single value
        "1,,2 * * * *",       # empty list item
        "1,* * * * *",        # empty-ish: '*' inside list is fine, so use real bad below
        "a * * * *",
        "MON * * * *",        # day name in minute field
        "* * * FOO *",
        "1.5 * * * *",
        "+5 * * * *",
        "-1 * * * *",
        "1-2-3 * * * *",
        "* * * * MON-",
        "*/ * * * *",
        "0 0 * * 0-8",
        "1-60 * * * *",
    ]

    def test_malformed_raise_value_error(self):
        for expr in self.bad:
            with self.subTest(expr=expr):
                if expr == "1,* * * * *":
                    continue  # valid: '1' and '*' in a list
                with self.assertRaises(ValueError):
                    next_run(expr, D(2026, 10, 11))

    def test_star_inside_list_is_valid(self):
        self.assertEqual(next_run("1,* * * * *", D(2026, 10, 11, 12, 0)), D(2026, 10, 11, 12, 1))


class NeverFires(unittest.TestCase):
