        with self.assertRaises(ValueError):
            next_run("0 0 31 2 *", D(2026, 10, 11))

    def test_apr_31_raises(self):
        with self.assertRaises(ValueError):
            next_run("0 0 31 4 *", D(2026, 10, 11))

    def test_near_datetime_max_raises_value_error(self):
